 16→  - "VEX examples"
 17→  - "Common VEX patterns"
 18→  - "How to do X in VEX"
 19→  - "VEX code snippets"
 20→---
 21→
 22→# VEX Common Patterns and Examples
 23→
 24→## Deformation Patterns
 25→
 26→### Sine Wave Deformation
 27→```vex
 28→// Point wrangle
 29→float amp = chf("amplitude");      // 0.5
 30→float freq = chf("frequency");     // 2.0
 31→float offset = chf("offset");      // 0.0
 32→
 33→@P.y += sin(@P.x * freq + offset + @Time) * amp;
 34→```
 35→
 36→### Noise Displacement Along Normal
 37→```vex
 38→// Point wrangle -- requires normals
 39→float amp = chf("amplitude");
 40→float freq = chf("frequency");
 41→float n = snoise(@P * freq + @Time * chf("speed"));
 42→@P += @N * n * amp;
 43→```
 44→
 45→### Twist Deformation
 46→```vex
 47→// Point wrangle
 48→float twist_amount = chf("twist") * @P.y;
 49→float c = cos(twist_amount);
 50→float s = sin(twist_amount);
 51→float x = @P.x * c - @P.z * s;
 52→float z = @P.x * s + @P.z * c;
 53→@P.x = x;
 54→@P.z = z;
 55→// Recompute normals after this (use Normal SOP or set @N manually)
 56→```
 57→
 58→### Taper
 59→```vex
 60→// Point wrangle
 61→float taper = chramp("taper_profile", fit(@P.y, chf("ymin"), chf("ymax"), 0, 1));
 62→@P.x *= taper;
 63→@P.z *= taper;
 64→```
 65→
 66→## Color Patterns
 67→
 68→### Color by Height
 69→```vex
 70→// Point wrangle
 71→float t = fit(@P.y, chf("min_height"), chf("max_height"), 0, 1);
 72→@Cd = chramp("color_ramp", t);
 73→```
 74→
 75→### Color by Curvature
 76→```vex
 77→// Point wrangle (requires normals)
 78→int pts[] = neighbours(0, @ptnum);
 79→float curvature = 0;
 80→foreach (int pt; pts) {
 81→    vector n2 = point(0, "N", pt);
 82→    curvature += 1.0 - dot(@N, n2);
 83→}
 84→curvature /= max(len(pts), 1);
 85→@Cd = chramp("curvature_ramp", curvature);
 86→```
 87→
 88→### Random Color Per Piece
 89→```vex
 90→// Point wrangle (requires i@piece or s@name attribute)
 91→int piece = i@piece;  // or use i@class
 92→float hue = rand(piece * 13.37);
 93→float sat = fit(rand(piece * 7.13), 0, 1, 0.5, 1.0);
 94→@Cd = hsvtorgb(set(hue, sat, 1.0));
 95→```
 96→
 97→## Geometry Generation
 98→
 99→### Spiral Points
100→```vex
101→// Detail wrangle
102→int npts = chi("num_points");
103→float radius = chf("radius");
104→float height = chf("height");
105→float turns = chf("turns");
106→
107→for (int i = 0; i < npts; i++) {
108→    float t = float(i) / float(npts - 1);
109→    float angle = t * turns * 2 * PI;
110→    float r = radius * (1.0 - t * chf("taper"));
111→    vector pos = set(cos(angle) * r, t * height, sin(angle) * r);
112→    int pt = addpoint(0, pos);
113→    setpointattrib(0, "pscale", pt, lerp(chf("scale_start"), chf("scale_end"), t), "set");
114→}
115→```
116→
117→### Connect Points as Polyline
118→```vex
119→// Detail wrangle (run after point creation)
120→int npts = npoints(0);
121→if (npts < 2) return;
122→
123→int prim = addprim(0, "polyline");
124→for (int i = 0; i < npts; i++) {
125→    addvertex(0, prim, i);
126→}
127→```
128→
129→### Grid from Scratch
130→```vex
131→// Detail wrangle
132→int rows = chi("rows");
133→int cols = chi("cols");
134→float spacing = chf("spacing");
135→
136→// Create points
137→int pts[];
138→resize(pts, rows * cols);
139→for (int r = 0; r < rows; r++) {
140→    for (int c = 0; c < cols; c++) {
141→        vector pos = set(c * spacing, 0, r * spacing);
142→        pts[r * cols + c] = addpoint(0, pos);
143→    }
144→}
145→
146→// Create quads
147→for (int r = 0; r < rows - 1; r++) {
148→    for (int c = 0; c < cols - 1; c++) {
149→        int p0 = pts[r * cols + c];
150→        int p1 = pts[r * cols + c + 1];
151→        int p2 = pts[(r+1) * cols + c + 1];
152→        int p3 = pts[(r+1) * cols + c];
153→        addprim(0, "poly", p0, p1, p2, p3);
154→    }
155→}
156→```
157→
158→## Grouping Patterns
159→
160→### Group by Bounding Box
161→```vex
162→// Point wrangle
163→vector bmin = chv("bbox_min");
164→vector bmax = chv("bbox_max");
165→i@group_inside = (@P.x >= bmin.x && @P.x <= bmax.x &&
166→                  @P.y >= bmin.y && @P.y <= bmax.y &&
167→                  @P.z >= bmin.z && @P.z <= bmax.z) ? 1 : 0;
168→```
169→
170→### Group by Normal Direction
171→```vex
172→// Point wrangle
173→vector up = {0, 1, 0};
174→float threshold = chf("angle_threshold");  // cos of angle, e.g. 0.7
175→i@group_upfacing = (dot(@N, up) > threshold) ? 1 : 0;
176→```
177→
178→### Group Every Nth Point
179→```vex
180→// Point wrangle
181→int n = chi("every_nth");
182→i@group_selected = (@ptnum % n == 0) ? 1 : 0;
183→```
184→
185→## Solver / Simulation Patterns
186→
187→### Point Advection (SOP Solver)
188→```vex
189→// Point wrangle inside SOP Solver
190→vector vel = v@v;
191→float dt = @TimeInc;
192→@P += vel * dt;
193→
194→// Add gravity
195→v@v += {0, -9.81, 0} * dt;
196→
197→// Ground collision
198→if (@P.y < 0) {
199→    @P.y = 0;
200→    v@v.y = abs(v@v.y) * chf("bounce");
201→    v@v *= chf("friction");
202→}
203→```
204→
205→### Attribute Decay Over Time
206→```vex
207→// Point wrangle (inside solver or with time dependency)
208→float decay = chf("decay_rate");  // e.g. 0.95
209→f@temperature *= pow(decay, @TimeInc * 30);  // Frame-rate independent
210→```
211→
212→## Transfer / Blend Patterns
213→
214→### Transfer Attribute by Proximity
215→```vex
216→// Point wrangle (source on input 1)
217→float radius = chf("radius");
218→int pts[] = pcfind(1, "P", @P, radius, chi("maxpts"));
219→
220→if (len(pts) > 0) {
221→    float total_w = 0;
222→    vector total_cd = {0,0,0};
223→    foreach (int pt; pts) {
224→        float d = distance(@P, point(1, "P", pt));
225→        float w = 1.0 - smooth(0, radius, d);
226→        total_cd += point(1, "Cd", pt) * w;
227→        total_w += w;
228→    }
229→    if (total_w > 0) {
230→        float blend = chf("blend");
231→        @Cd = lerp(@Cd, total_cd / total_w, blend);
232→    }
233→}
234→```
235→
236→### Smooth / Relax Points
237→```vex
238→// Point wrangle (iterate multiple times via feedback loop)
239→int pts[] = neighbours(0, @ptnum);
240→if (len(pts) == 0) return;
241→
242→vector avg = {0,0,0};
243→foreach (int pt; pts) {
244→    avg += point(0, "P", pt);
245→}
246→avg /= len(pts);
247→
248→float strength = chf("smooth_strength");  // 0.1 - 0.5
249→@P = lerp(@P, avg, strength);
250→```
251→
252→### Edge Detection
253→```vex
254→// Point wrangle
255→int pts[] = neighbours(0, @ptnum);
256→float max_diff = 0;
257→foreach (int pt; pts) {
258→    float diff = abs(@density - point(0, "density", pt));
259→    max_diff = max(max_diff, diff);
260→}
261→f@edge = max_diff;
262→i@group_edges = (max_diff > chf("edge_threshold")) ? 1 : 0;
263→```
264→
265→---
266→*Houdini 21 VEX Reference -- Common Patterns*
267→

