python -c "
import json, glob, os

# Check all possible MCP config locations
locations = [
    os.path.expanduser('~/.claude/settings.local.json'),
    os.path.expanduser('~/.claude/settings.json'),
    os.path.expanduser('~/AppData/Roaming/Claude/claude_desktop_config.json'),
    os.path.expanduser('~/.claude.json'),
]

# Also check for .mcp.json files
for g in glob.glob(os.path.expanduser('~/**/.mcp.json'), recursive=False):
    locations.append(g)
locations.append(os.path.expanduser('~/.mcp.json'))

for loc in locations:
    if os.path.exists(loc):
        try:
            d = json.load(open(loc))
            # Look for anything with 'synapse' or 'mcp' in keys
            for key in d:
                if 'mcp' in key.lower() or 'synapse' in key.lower() or 'server' in key.lower():
                    print(f'{loc}: {key} = {json.dumps(d[key], indent=2)[:500]}')
        except:
            pass
    else:
        pass

# Check project-level .mcp.json
for root in ['C:/Users/User', 'C:/Users/User/Synapse']:
    mcp_json = os.path.join(root, '.mcp.json')
    if os.path.exists(mcp_json):
        print(f'Found: {mcp_json}')
        print(json.dumps(json.load(open(mcp_json)), indent=2)[:500])
